  "epitaphs": [
    {
      "name": "Screams Halloween Theme Park",
      "place": "Waxahachie",
      "note": "1996-2024. Five-attraction Halloween park on FM 66. The 2024 season was the last."
    },
    {
      "name": "Tayman Graveyard",
      "place": "Midlothian",
      "note": "2005-2021. Built on the grounds of the earlier Tayman Manor."
    },
    {
      "name": "Dallas Scaregrounds",
      "place": "Dallas Design District",
      "note": "Grew out of Dr. Blood's into a haunt festival. Closed when the Design District was redeveloped."
    },
    {
      "name": "Fatal End / The Dollhouse",
      "place": "Dallas West End",
      "note": "Opened in the late 2000s. Necroplex merged with it in 2011. Redevelopment ended the run."
    },
    {
      "name": "Dallas Slaughterhouse",
      "place": "Dallas",
      "note": "Started in the West End, moved to Deep Ellum, and merged with J&F in Garland in 2016."
    },
    {
      "name": "Dungeon of Doom",
      "place": "Arlington",
      "note": "Original show was in the Arlington Museum of Art basement and closed after 2007."
    },
    {
      "name": "Necroplex",
      "place": "Italy, Texas",
      "note": "Opened in 2008 south of Waxahachie and merged with Fatal End in 2011."
    },
    {
      "name": "Tayman Manor",
      "place": "Midlothian",
      "note": "Intense 1990s and early-2000s haunt. Lost in a fire, along with most of neighboring Addamsville."
    },
    {
      "name": "Addamsville",
      "place": "Midlothian",
      "note": "Haunt park beside Tayman Manor, open only in 2002 and 2003."
    },
    {
      "name": "Dr. Haunt's Chamber of Fear",
      "place": "Gainesville",
      "note": "Roadside haunt staffed by college volunteers through the 2000s."
    },
    {
      "name": "Terrorplex",
      "place": "Mansfield",
      "note": "Small park of four or five houses south of Arlington. Mead Manor was the strongest of them."
    },
    {
      "name": "Lafitte's Landing",
      "place": "Allen",
      "note": "Pirate-themed house from the mid-2000s, with one later season in Allen."
    },
    {
      "name": "Phantom's Haunted House",
      "place": "Lewisville / Frisco / Allen",
      "note": "Moved from Lewisville to Frisco, spent three seasons at the State Fair, and finished in Allen."
    },
    {
      "name": "Faustas Sanitarium",
      "place": "Cleburne",
      "note": "Upstairs in Wright Plaza from the 1990s until about 2003."
    },
    {
      "name": "Haunt House",
      "place": "Caddo Mills",
      "note": "Small haunt off the I-30 access road. Early user of shock pads."
    },
    {
      "name": "Ripley's Haunted House",
      "place": "Grand Prairie",
      "note": "Wax-museum haunt inside Ripley's during the 2000s."
    },
    {
      "name": "Strangling Brothers Haunted Circus",
      "place": "Irving / Grand Prairie",
      "note": "Trailer-circus haunt for three DFW seasons starting in 2013. A Utah version continued."
    },
    {
      "name": "Reindeer Manor / 13th Street Morgue",
      "place": "Red Oak / Waxahachie",
      "note": "Opened in 1974 in Red Oak. After late moves to Grand Prairie and Waxahachie, 2025 was the final season."
    }
  ],
